                                <span>MEV Protected</span>
                            </div>
                            <div className="text-[9px] text-zinc-600 font-mono">
                                Latency: 2ms
                            </div>
                        </div>
                    )}
                </div>

                {/* Empty Spacer */}
                <div className="flex-1"></div>

             </div>
          )}

      </section>

      {/* CONFIRMATION MODAL */}
      <ReviewModal 
        isOpen={isReviewOpen} 
        onClose={() => setIsReviewOpen(false)} 
        onConfirm={handleConfirmOrder} 
        type={tradeMode === 'algo' ? 'ALGO' : tradeMode === 'limit' ? 'LIMIT' : 'SWAP'} 
        data={reviewData}
      />
    </div>
  );
};

