                            </div>
                        </div>

                        {/* --- DYNAMIC CONTROLS --- */}

                        {/* 1. TWAP CONTROLS */}
                        {algoStrategy === 'TWAP' && (
                            <div className="space-y-6 animate-in fade-in slide-in-from-top-2">
                                {/* Duration */}
                                <div>
                                    <div className="flex justify-between mb-2">
                                        <label className="text-[9px] font-bold text-zinc-500 uppercase tracking-wide">Duration</label>
