              let bVal: any = b[sortConfig.key];

              // Custom Sort: TVL (Parse String)
              if (sortConfig.key === 'tvl') {
                  const parseTVL = (s: string) => {
                      const num = parseFloat(s.replace(/[^0-9.]/g, ''));
                      const mult = s.includes('B') ? 1e9 : s.includes('M') ? 1e6 : 1;
                      return num * mult;
