                  aVal = riskWeight[a.risk];
                  bVal = riskWeight[b.risk];
              }

              if (aVal < bVal) return sortConfig.direction === 'asc' ? -1 : 1;
              if (aVal > bVal) return sortConfig.direction === 'asc' ? 1 : -1;
              return 0;
